import {Scrubber,encodings,blobEncodings,compileScrubPattern} from '../../../../../src/core/scrub.js';
const entries=[{secret:'test-secret-fake/value',label:'test',replacement:'<REDACTED>'},{secret:'test-café-秘密',label:'unicode',replacement:'<UNICODE>'},{secret:'tiny',always:true,label:'short',replacement:'<SHORT>'}];const texts=['ordinary disk-usage_by_repository_over_time task-oriented_approach_to_the_problem','ghp_'+ 'a'.repeat(30),'sk-proj-'+ 'b'.repeat(30),'xoxb-'+ 'c'.repeat(20)];for(const e of entries)for(const x of encodings(e.secret,e.always?1:8))texts.push('before '+x+' after');
const secret=entries[0].secret;const base=Buffer.from(secret).toString('base64');const hex=Buffer.from(secret).toString('hex');for(const width of [1,3,8,16,64]){texts.push(base.match(new RegExp(`.{1,${width}}`,'g')).join('\n'));texts.push(hex.match(new RegExp(`.{1,${width}}`,'g')).join('\\n'));}let turn=0;const mixed=hex.replace(/[a-f]/g,c=>turn++%2?c.toUpperCase():c);texts.push(mixed);texts.push(mixed.match(/.{1,8}/g).join('\n'));texts.push('%74'+secret.slice(1));texts.push('\\u0074'+secret.slice(1));for(const x of [base,hex])texts.push([...x].map(c=>'%'+c.charCodeAt(0).toString(16)).join(''));texts.push(JSON.stringify([...base].map(c=>'%'+c.charCodeAt(0).toString(16)).join('')).slice(1,-1));texts.push('\\u005c'+'u0074'+secret.slice(1));
texts.push('\\u0074est-secret-fake\\/value');const stack='\\u0074'+secret.slice(1);texts.push(Buffer.from([...stack].map(c=>'%'+c.charCodeAt(0).toString(16)).join('')).toString('base64'));const cases=texts.map(text=>({text,result:new Scrubber(entries).scrub(text)}));const patterns=['abc[A-Z]{4,8}','abc[^Q]{0,256}[^Q]{256}Q','abc[A-Z]{256}[A-Z]{256}','abc[0-9]{2}[A-Z]{4,8}END','abc.*','(abc)','abc|def','disk-usage_by_repository_over_time','abc\\d{2,4}','abc[A-Z]{2,4}?','ab','abc[A-Z]{257}','abc[A-Z]{3,2}','abc[A-Z]{2,}','abc[A-Z]{1,2}x?','abc[]','abc[[]'];const compiled=patterns.map(source=>{try{compileScrubPattern(source);return{source,ok:true}}catch(e){return{source,ok:false,detail:e.detail}}});console.log(JSON.stringify({entries,cases,compiled,encodings:entries.map(e=>({secret:e.secret,encodings:encodings(e.secret,1),blobs:blobEncodings(e.secret)}))}));
